(
  'P04', 'BS01', 'foundation', 'NEN', 1, 'numeric', 'approved',
  '{"id":"P04","stationId":"BS01","stage":"foundation","cluster":"NEN","skill_ids":["right_triangle_trig"],"level":1,"type":"numeric","stem_vi":"Cho tam giác $ABC$ vuông tại $A$ có cạnh huyền $BC = 10\\text{ m}$ và $\\widehat{B} = 30^\\circ$. Tính độ dài cạnh $AC = BC\\cdot\\sin 30^\\circ$.","expected_answer":{"value":5,"rounded":5,"decimal_places":0,"unit":"m"},"fixedUnitLabel":"m","math_params":{"kind":"sine_law_side","c":10,"angleA":60,"angleB":30,"angleC":90},"solution_vi":"Trong tam giác $ABC$ vuông tại $A$, $AC = BC\\cdot\\sin 30^\\circ = 10 \\cdot 0{,}5 = 5\\text{ m}$.","anticipated_error_ids":["E06","E01"],"hints_vi":["Trong tam giác vuông, cạnh đối diện góc nhọn bằng cạnh huyền nhân sin góc đó.","Thay $BC = 10$ và $\\sin 30^\\circ = 0{,}5$ để tính $AC$."],"review_status":"approved","reviewedBy":"curriculum_verified","source_refs":["SGK_KNTT_B5_p33_37"],"is_adapted":true,"version":2}'::jsonb
),
(
  'R04', 'BS01', 'remediation', 'NEN', 1, 'numeric', 'approved',
  '{"id":"R04","stationId":"BS01","stage":"remediation","cluster":"NEN","skill_ids":["sine_law","rounding"],"level":1,"type":"numeric","stem_vi":"Áp dụng Định lí Sin trong tam giác $ABC$ có $a = 10\\text{ m}$, $\\widehat{A} = 45^\\circ$, $\\widehat{B} = 30^\\circ$. Tính độ dài cạnh $b = \\frac{10\\sin 30^\\circ}{\\sin 45^\\circ}$ (làm tròn đến $0{,}1\\text{ m}$).","expected_answer":{"exact_numeric":7.0710678118654755,"rounded":7.1,"decimal_places":1,"unit":"m"},"fixedUnitLabel":"m","math_params":{"kind":"sine_law_side","a":10,"angleA":45,"angleB":30},"solution_vi":"$b = \\frac{10 \\cdot 0{,}5}{\\frac{\\sqrt{2}}{2}} = 5\\sqrt{2} \\approx 7{,}07\\text{ m}$, làm tròn đến $0{,}1\\text{ m}$ được $7{,}1\\text{ m}$.","anticipated_error_ids":["E05","E07"],"hints_vi":["Thay $\\sin 30^\\circ = 0{,}5$ và $\\sin 45^\\circ = \\frac{\\sqrt{2}}{2}$ vào biểu thức tính $b$.","Bấm máy ở chế độ độ (DEG) rồi làm tròn kết quả cuối đến hàng phần mười ($0{,}1\\text{ m}$)."],"review_status":"approved","reviewedBy":"curriculum_verified","source_refs":["SGK_KNTT_B6_p39_40"],"is_adapted":true,"version":2}'::jsonb
),
(
  'CH3_NEN_03', 'QS01', 'practice', 'NEN', 2, 'mcq', 'approved',
  '{"id":"CH3_NEN_03","stationId":"QS01","stage":"practice","cluster":"NEN","skill_ids":["cosine_law","angle_classification"],"level":2,"type":"mcq","stem_vi":"Trong tam giác $ABC$ có ba cạnh $a, b, c$, theo hệ quả Định lí Côsin ($\\cos C = \\frac{a^2 + b^2 - c^2}{2ab}$), khẳng định nào sau đây đúng khi $\\widehat{C}$ là góc tù?","options":[{"id":"a","label":"$a^2 + b^2 < c^2$ (vì $\\cos C < 0$)"},{"id":"b","label":"$a^2 + b^2 > c^2$ (vì $\\cos C > 0$)","errorCode":"E09"},{"id":"c","label":"$a^2 + b^2 = c^2$ (vì $\\cos C = 0$)","errorCode":"E09"},{"id":"d","label":"$a^2 + b^2 = 2c^2$","errorCode":"E08"}],"expected_answer":{"choice":"a"},"solution_vi":"Khi $\\widehat{C}$ là góc tù ($90^\\circ < \\widehat{C} < 180^\\circ$) thì $\\cos C < 0$, nên từ $\\cos C = \\frac{a^2 + b^2 - c^2}{2ab}$ suy ra $a^2 + b^2 - c^2 < 0 \\Leftrightarrow a^2 + b^2 < c^2$.","anticipated_error_ids":["E09","E08"],"hints_vi":["Xét dấu của $\\cos C$ khi $90^\\circ < \\widehat{C} < 180^\\circ$.","Vì mẫu số $2ab > 0$, dấu của $\\cos C$ trùng với dấu của tử số $a^2 + b^2 - c^2$."],"review_status":"approved","reviewedBy":"curriculum_verified","source_refs":["SGK_KNTT_B6_COS"],"is_adapted":true,"version":2}'::jsonb
),
(
