  '{"id":"CH3_NEN_04","stationId":"QS01","stage":"practice","cluster":"NEN","skill_ids":["right_triangle_trig","opposite_pair"],"level":2,"type":"numeric","stem_vi":"Cho tam giác $ABC$ vuông tại $A$ có cạnh huyền $BC = 20\\text{ m}$ và $\\widehat{B} = 30^\\circ$. Tính độ dài cạnh góc vuông $AC$.","expected_answer":{"exact_numeric":10,"rounded":10,"decimal_places":0,"unit":"m"},"fixedUnitLabel":"m","math_params":{"kind":"sine_law_side","c":20,"angleA":60,"angleB":30,"angleC":90},"solution_vi":"Trong tam giác $ABC$ vuông tại $A$, cạnh $AC$ đối diện góc $\\widehat{B}$ nên $AC = BC\\cdot\\sin 30^\\circ = 20 \\cdot 0{,}5 = 10\\text{ m}$.","anticipated_error_ids":["E01","E06"],"hints_vi":["Trong tam giác vuông tại $A$, cạnh $AC$ là cạnh đối của góc $\\widehat{B}$ còn $BC$ là cạnh huyền.","Áp dụng hệ thức $AC = BC\\cdot\\sin B$ với $\\sin 30^\\circ = 0{,}5$."],"review_status":"approved","reviewedBy":"curriculum_verified","source_refs":["SGK_KNTT_B5_B6"],"is_adapted":true,"version":2}'::jsonb
